def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores,
    and if a string has more than 2 consecutive spaces, then replace all consecutive spaces with -
    """
    result = []
    space_count = 0

    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count > 2:
                result.append('-')
            elif space_count == 2:
                result.append('_')
            else:
                result.append(char)
            space_count = 0

    if space_count > 2:
        result.append('-')
    elif space_count == 2:
        result.append('_')

    return ''.join(result)
```

