from typing import Dict

def check_dict_case(dict_: Dict[str, str]) -> bool:
    """
    Given a dictionary, return True if all keys are strings in lower case or all keys are strings in upper case,
    else return False.

    The function should return False is the given dictionary is empty.
    """
    if not dict_:
        return False

    first_key_case = None
    for key in dict_:
        if not isinstance(key, str):
            return False

        if first_key_case is None:
            first_key_case = key.islower() or key.isupper()

        if (key.islower() and not first_key_case) or (key.isupper() and not first_key_case):
            return False

    return True
```

