from typing import List

def histogram(text: str) -> dict:
    """
    Given a string representing space-separated lowercase letters,
    return a dictionary of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    >>> histogram('a b c')
    {'a': 1, 'b': 1, 'c': 1}
    >>> histogram('a b a')
    {'a': 2}
    >>> histogram('b b a')
    {'b': 4}
    >>> histogram('')
    {}
    """
    letter_counts = {}
    for letter in text.split():
        if letter in letter_counts:
            letter_counts[letter] += 1
        else:
            letter_counts[letter] = 1

    max_count = max(letter_counts.values(), default=0)
    return {letter: count for letter, count in letter_counts.items() if count == max_count}
```

